import { build } from 'esbuild';
import { readFile, writeFile, mkdir, readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const resources = path.resolve(root, '../../Sources/MooToolNextCore/Resources');
const bytes = async file => `Uint8Array.from(atob(${JSON.stringify((await readFile(path.join(root, file))).toString('base64'))}), c => c.charCodeAt(0))`;
const tree = await bytes('node_modules/web-tree-sitter/web-tree-sitter.wasm');
const grammar = await bytes('node_modules/prettier-plugin-java/dist/tree-sitter-java_orchard.wasm');
const outfile = path.join(resources, 'ReformatTools.js');
await build({
  absWorkingDir: root, entryPoints: ['entry.js'], outfile, bundle: true, format: 'iife', platform: 'browser', target: 'safari17', minify: true,
  external: ['module', 'fs/promises', 'node:module', 'node:fs/promises'],
  define: { 'import.meta.url': '"embedded:formatter"', 'process': 'undefined' },
  banner: { js: '// Generated by vendor/formatters/build.mjs. Licenses: formatters-licenses/.\n' },
  plugins: [{ name: 'native-embedded-java-wasm', setup(builder) {
    builder.onLoad({ filter: /prettier-plugin-java\/dist\/index\.mjs$/ }, async ({ path: filename }) => {
      let source = await readFile(filename, 'utf8');
      for (const [from, to] of [
        ['await Parser.init();', `await Parser.init({ wasmBinary: ${tree}, locateFile: () => 'embedded.wasm' });`],
        ['new URL("./tree-sitter-java_orchard.wasm", import.meta.url)', grammar]
      ]) {
        if (source.split(from).length !== 2) throw new Error('Java loader changed: ' + from);
        source = source.replace(from, to);
      }
      return { contents: source, loader: 'js', resolveDir: path.dirname(filename) };
    });
  } }]
});

const licenses = path.join(resources, 'formatters-licenses');
await mkdir(licenses, { recursive: true });
const lock = JSON.parse(await readFile(path.join(root, 'package-lock.json'), 'utf8'));
const packages = [];
for (const [relative, entry] of Object.entries(lock.packages)) {
  if (!relative || entry.dev || entry.optional) continue;
  const directory = path.join(root, relative), pkg = JSON.parse(await readFile(path.join(directory, 'package.json'), 'utf8'));
  const noticeFiles = (await readdir(directory)).filter(name => /^(license|notice|third-party-notices)(\.|$)/i.test(name));
  if (!noticeFiles.length) throw new Error('Missing license for ' + pkg.name);
  for (const name of noticeFiles) await writeFile(path.join(licenses, pkg.name.replaceAll('/', '-') + '-' + name), await readFile(path.join(directory, name)));
  packages.push({ name: pkg.name, version: pkg.version, license: pkg.license, integrity: entry.integrity });
}
await writeFile(path.join(resources, 'formatter-versions.json'), JSON.stringify({
  bundleSHA256: createHash('sha256').update(await readFile(outfile)).digest('hex'), packages,
  adaptations: ['Java WASM runtime and grammar embedded as byte arrays; no file or network loading.']
}, null, 2) + '\n');
